text:
@import url("reset.css");
@import url("fonts.css");
@import url("swiper-bundle.css");
@import url("guideline.css");
@import url("base.css");
@import url("layout.css");
@import url("contents.css");
@import url("disaster-information.css");
@import url("pop.css");
@import url("temp.css");

.mbanner { width: 100%; height: 261px; overflow: hidden; border-radius: 10px; text-align: center; }
.mbanner a { display: unset; }
.mbanner a img { width: auto !important; }
.mbanner a:focus-visible { outline-offset: -10px; border-radius: 10px; width: 100%; height: 100%; outline: rgb(236, 28, 36) solid 130px !important; }
.main-content { display: flex; max-width: 100%; min-height: 500px; margin: auto; transition: margin-left 0.3s; }
.content-main { flex-grow: 1; padding: 30px 0px 40px; width: 100%; }
.quick-list li { width: 16.5% !important; }
.safebox-infoarea { float: left; margin-bottom: 40px; min-height: 365px; height: 470px; }
.new-secondcon { overflow: hidden; display: block !important; }
.new-main { position: relative; height: 360px; overflow-y: auto !important; }
.main-more { position: absolute; top: -60px; right: 18px; }
.main-more button { border: 1px solid rgb(221, 221, 221); padding: 5px 12px; border-radius: 5px; }
.tab_bt { padding-bottom: 10px; margin-bottom: 10px; border-bottom: 1px solid rgb(221, 221, 221); }
.tab_bt button { padding: 0px 20px; color: rgb(115, 115, 115); transition: font-size 0.2s; font-size: 1.5em; font-weight: bold; }
.tab_bt button.active { color: rgb(0, 0, 0); font-size: 1.9em; }
.first-bt { background: url("../images/main/main-tab-bar.jpg") right 12px no-repeat; }
.new-main-con { overflow: hidden; padding: 10px 10px 0px; }
.new-main-con h4 { font-size: 1.7rem; padding: 5px 0px 10px 30px; font-weight: 600; }
.wsn-stw { background: url("../images/main/situation-icon1-m.jpg") left 12px no-repeat; }
.wsn-st { background: url("../images/main/situation-icon2-m.jpg") left 15px no-repeat; }
.wsn-dp { background: url("../images/main/situation-icon3-m.jpg") left 12px no-repeat; }
.wsn-cw { background: url("../images/main/situation-icon4-m.jpg") left 11px no-repeat; }
.wsn-hs { background: url("../images/main/situation-icon5-m.jpg") left 10px no-repeat; }
.wsn-dy { background: url("../images/main/situation-icon6-m.jpg") left 15px no-repeat; }
.wsn-ss { background: url("../images/main/situation-icon7-m.jpg") left 12px no-repeat; }
.wsn-th { background: url("../images/main/situation-icon8-m.jpg") left 12px no-repeat; }
.wsn-yd { background: url("../images/main/situation-icon9-m.jpg") left 12px no-repeat; }
.wsn-hw { background: url("../images/main/situation-icon10-m.jpg") left 12px no-repeat; }
.wsn-eq { background: url("../images/main/situation-icon11-m.jpg") left 12px no-repeat; }
.wsn-ff { background: url("../images/main/situation-icon12-m.jpg") left 8px no-repeat; }
.new-main-con span.fire_red { background: red; }
.new-main-con span.fire_gray { background: rgb(85, 85, 85); }
.new-main-con span.fire_green { background: green; }
.new-main-con { overflow: auto; height: auto; }
.new-main-con dl { margin-bottom: 21px; }
.new-main-con dl dt { position: relative; }
.new-main-con dl dt button { position: absolute; top: 3px; left: 270px; border: 1px solid rgb(221, 221, 221); padding: 5px 15px; border-radius: 5px; }
.new-main-con dl dt button.ptn-l { left: 135px; }
.new-main-con dl dd { font-size: 1.2rem; line-height: 30px; }
.new-main-con dl dd a { height: 30px; width: calc(95% - 95px); }
.new-main-con dl dd span { width: 106px; height: 30px; line-height: 30px; padding: 0px 10px; font-size: 1.1rem; }
.new-main-con ul { margin-top: 5px; }
.new-main-con ul li { position: relative; margin-bottom: 10px; }
.new-main-con ul li button { position: absolute; top: 3px; right: 0px; border: 1px solid rgb(221, 221, 221); padding: 5px 15px; border-radius: 5px; }
.new-main-con ul li button.ptn-l { right: 120px; }
.new-main-con ul li { font-size: 1.2rem; line-height: 30px; }
.new-main-con ul li div { display: inline-block; width: 85%; }
.new-main-con ul li div a { height: 25px; width: calc(100% - 0px); }
.new-main-con ul li div p { height: 25px; margin-top: -5px; font-size: 16px; color: rgb(102, 102, 102); }
.new-main-con ul li span { width: 12%; height: 30px; line-height: 30px; padding: 0px 10px; font-size: 1.1rem; }
.message-area { float: right; height: 343px; margin-bottom: 35px; }
.main-thirdcon-new { display: inline-block; padding: 20px; width: 65% !important; }
.news-list { margin-top: 15px; }
.no-data { width: 100%; padding: 80px 0px; background: url("../images/common/no-data.jpg") center 0px no-repeat; margin-top: 30px; text-align: center; color: rgb(153, 153, 153); font-size: 1.1rem; }
.main-firstcon { width: 1400px; margin: 0px auto 10px; justify-content: space-between; display: flex; }
.total-searcharea { padding-bottom: 0px; display: inline-block; width: 65%; }
.weather-information { display: inline-block; margin-left: 10px; padding-top: 5px; width: 100%; }
.weather-information img { display: inline-block; vertical-align: top; width: 40px; }
.weather-information .weather-maininform { display: inline-block; padding: 10px 0px 0px 10px; vertical-align: top; }
.weather-maininform { width: 62.5%; }
.weather-maininform p { width: 100px; float: right; text-align: center; }
.weather-information h3 { display: inline-block; font-size: 16px; }
.weather-information h3 span { color: rgb(0, 116, 229); }
.weather-informlist { display: inline-block; padding-left: 10px; }
.w-inform li { display: inline-block; margin-right: 10px; }
.weather-information2 { position: relative; float: right; display: inline-block; margin-bottom: 20px; padding: 20px 35px; width: 32%; border: 1px solid rgb(221, 221, 221); border-radius: 15px; }
.weather-information2 img { display: inline-block; vertical-align: top; width: 40px; }
.weather-information2 .weather-maininform2 { display: inline-block; padding: 10px 0px 0px 10px; vertical-align: top; }
.weather-maininform2 { width: 80.5%; }
.weather-maininform2 p { width: 100px; float: right; text-align: center; }
.weather-information2 h3 { display: inline-block; font-size: 16px; }
.weather-information2 h3 span { color: rgb(0, 116, 229); }
.weather-informlist2 { display: inline-block; padding: 5px 0px 0px 10px; }
.w-inform2 li { display: inline-block; margin-right: 5px; }
.total-searchform { border: 2px solid rgb(34, 34, 34); height: 54px; line-height: 54px; width: 100%; margin: 0px auto; border-radius: 80px; display: flex; }
.total-searchform h3 { font-size: 22px; color: rgb(34, 34, 34); font-weight: 600; width: 18%; height: 54px; line-height: 50px; padding-left: 5%; display: inline-block; text-align: left; }
.total-searchform input { width: 88%; height: 50px; margin: 0px 0px 0px 30px; padding: 2px 0px 0px; border: 0px; display: inline-block; }
.total-searchform input::placeholder { color: rgb(156, 156, 156); font-size: 20px; font-weight: 400; }
.btn-totalsearch { width: 6%; display: inline-block; font-size: 0px; background: url("../images/main/tatal-search.png") 100% 50% no-repeat; }
.total-searchtxt { text-align: center; padding-top: 15px; }
.total-searchtxt h4 { display: inline-block; color: rgb(135, 134, 134); font-size: 16px; padding-right: 10px; font-weight: 500; }
.total-searchtxt .search-textlist { display: inline-block; }
.search-textlist li { display: inline-block; padding: 5px 10px; border-radius: 80px; color: rgb(135, 134, 134); font-size: 16px; font-weight: 500; background-color: rgb(237, 237, 237); }
.weather-area { display: inline-block; }
.main-secondcon { display: flex; flex-wrap: wrap; width: 1400px; margin: 0px auto; }
.weather-infoarea { width: 31%; margin-right: 3%; background-color: rgb(240, 243, 255); border: 1px solid rgb(211, 213, 237); padding: 20px; border-radius: 20px; }
.weather-inform1 { width: 100%; display: flex; justify-content: space-between; border-bottom: 2px dashed rgb(211, 213, 237); padding-bottom: 25px; margin-bottom: 25px; }
.weather-inform1 h3 { font-size: 30px; color: rgb(34, 34, 34); font-weight: 600; }
.weather-inform1 h3 span { display: block; color: rgb(51, 62, 179); }
.temp-info { color: rgb(34, 34, 34); font-size: 50px; padding-top: 20px; font-weight: 700; }
.weather-inform2 { width: 100%; background: url("../images/main/weather-img1.png") 0px 0px no-repeat; height: 114px; padding-left: 150px; }
.weater-other li { font-size: 22px; color: rgb(102, 102, 102); padding-bottom: 10px; }
.weater-other li:last-child { padding-bottom: 0px; }
.weater-other li span { color: rgb(34, 34, 34); font-weight: 600; }
.weater-other li .temp-down { color: rgb(79, 88, 181); }
.weater-other li .temp-up { color: rgb(199, 61, 42); }
.safe-inform { width: 31%; margin-right: 3%; background-color: rgb(244, 244, 244); border: 1px solid rgb(214, 214, 214); padding: 35px; border-radius: 20px; }
.safe-inform h3 { font-size: 30px; color: rgb(34, 34, 34); padding-bottom: 18px; }
.calam-listarea { width: 100%; display: flex; margin-bottom: 20px; }
.calam-listarea li { margin-right: 5px; background-color: rgb(255, 255, 255); border: 1px solid rgb(221, 231, 240); width: 32%; text-align: center; height: 75px; border-radius: 10px; font-size: 18px; color: rgb(34, 34, 34); font-weight: 500; padding-top: 10px; box-sizing: border-box; }
.calam-listarea li div { display: block; padding-bottom: 5px; }
.calam-listarea li div span { display: inline-block; width: 22px; background-color: rgb(34, 34, 34); border-radius: 50%; height: 22px; text-align: center; line-height: 22px; color: rgb(255, 255, 255); font-size: 16px; font-weight: 500; margin-right: 5px; }
.calam-guidelist { width: 100%; text-align: center; }
.calam-guidelist a { display: inline-block; font-size: 16px; color: rgb(34, 34, 34); font-weight: 500; margin: 0px 10px; }
.calam-guidelist a span { display: block; font-size: 0px; width: 55px; height: 55px; border-radius: 50%; overflow: hidden; margin-bottom: 10px; box-shadow: rgba(0, 0, 0, 0.02) 2px 5px 5px; transition: 0.3s; }
.calam-guidelist a:nth-child(1) span { background: url("../images/main/weat-icon1.png") 50% 50% no-repeat rgb(255, 255, 255); }
.calam-guidelist a:nth-child(2) span { background: url("../images/main/weat-icon2.png") 50% 50% no-repeat rgb(255, 255, 255); }
.calam-guidelist a:nth-child(3) span { background: url("../images/main/weat-icon3.png") 50% 50% no-repeat rgb(255, 255, 255); }
.calam-guidelist a:nth-child(4) span { background: url("../images/main/weat-icon4.png") 50% 50% no-repeat rgb(255, 255, 255); }
.calam-guidelist a:nth-child(1):hover span { background: url("../images/main/weat-icon1-on.png") 50% 50% no-repeat rgb(34, 34, 34); }
.calam-guidelist a:nth-child(2):hover span { background: url("../images/main/weat-icon2-on.png") 50% 50% no-repeat rgb(34, 34, 34); }
.calam-guidelist a:nth-child(3):hover span { background: url("../images/main/weat-icon3-on.png") 50% 50% no-repeat rgb(34, 34, 34); }
.calam-guidelist a:nth-child(4):hover span { background: url("../images/main/weat-icon4-on.png") 50% 50% no-repeat rgb(34, 34, 34); }
.message-area { width: 32%; background-color: rgb(235, 245, 255); border: 1px solid rgb(193, 216, 238); padding: 25px 35px; border-radius: 15px; position: relative; margin-left: 3%; }
.message-titlearea { display: flex; justify-content: space-between; border-bottom: 1px solid rgb(193, 216, 238); padding-bottom: 23px; height: 50px; font-size: 36px; }
.guide-title span { color: rgb(0, 116, 229); }
.message-btnarea { position: absolute; top: 30px; right: 35px; }
.message-list { width: 100%; }
.message-list li { margin: 15px 0px; }
.message-list li a { font-size: 18px; color: rgb(34, 34, 34); padding-bottom: 5px; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 3; max-height: 70px; -webkit-box-orient: vertical; }
.dateinfom { margin-top: 7px; font-size: 16px; color: rgb(102, 102, 102); overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 1; max-height: 25px; -webkit-box-orient: vertical; }
.dateinfom span { display: inline-block; padding-left: 15px; font-size: 16px; color: rgb(136, 136, 136); }
.message-list li:last-child { padding-top: 10px; margin-bottom: 0px; }
.main-thirdcon { padding: 0px; margin: 10px 0px 55px; position: relative; }
.main-thirdcon h3 { font-size: 1.937rem; color: rgb(34, 34, 34); font-weight: 600; padding-bottom: 30px; display: inline-block; }
.main-thirdcon .icon-setting a { background: url("../images/main/setting-icon.png") 85% 50% no-repeat rgb(34, 34, 34); padding: 5px 30px 5px 10px; border-radius: 50px; color: rgb(255, 255, 255); float: right; cursor: pointer; position: absolute; top: 10px; right: 10px; }
.quick-list { display: flex; justify-content: center; flex-wrap: wrap; }
.quick-list li { width: 12.5%; text-align: center; }
.quick-list li a { font-size: 19px; color: rgb(34, 34, 34); font-weight: 600; white-space: pre; }
.quick-list li span { display: block; font-size: 0px; width: 120px; height: 120px; padding-top: 30px; border-radius: 50%; margin: 0px auto 10px; transition: 0.3s; background: rgb(235, 245, 255); border: 1px solid rgb(235, 245, 255); }
.quick-list li:hover span { background: rgb(255, 255, 255); border: 1px solid rgb(184, 184, 184); box-shadow: rgba(0, 0, 0, 0.15) 3px 5px 5px; }
.quick-list li.active span { background: rgb(255, 255, 255); border: 2px dashed rgb(23, 100, 196); box-shadow: rgba(0, 0, 0, 0.15) 3px 5px 5px; }
.quick-list li.active:hover span { background: rgb(255, 255, 255); border: 2px dashed rgb(23, 100, 196); box-shadow: rgba(0, 0, 0, 0.15) 3px 5px 5px; }
.main-fourthcon { width: 63%; float: left; }
.fourth-inner { width: 100%; padding-bottom: 35px; }
.guide-title { font-size: 1.937rem; color: rgb(34, 34, 34); font-weight: 600; margin-bottom: 15px; }
.popzone-titlearea h3.guide-title { display: none; }
.guideline-list { display: flex; flex-wrap: wrap; }
.guideline-list li { width: 23%; margin: 0px 2% 2% 0px; height: 140px; text-align: center; border: 1px solid rgb(223, 223, 223); background-color: rgb(255, 255, 255); border-radius: 15px; transition: 0.3s; }
.guideline-list li:nth-child(4), .guideline-list li:nth-child(8) { margin-right: 0px; }
.guideline-list li:nth-child(5), .guideline-list li:nth-child(6), .guideline-list li:nth-child(7), .guideline-list li:nth-child(8) { margin-bottom: 0px; }
.guideline-list li a { display: block; font-size: 24px; color: rgb(34, 34, 34); font-weight: 600; }
.guideline-list li span { display: block; width: 70px; height: 70px; background-color: rgb(241, 241, 241); border-radius: 50%; margin: 20px auto 5px; transition: 0.3s; }
.guideline-list li:hover { border: 1px solid rgb(0, 116, 229); box-shadow: rgba(0, 0, 0, 0.15) 3px 6px 6px; }
.guideline-list li:hover span { background-color: rgb(169, 204, 255); }
.popzone-area { width: 450px; height: 300px; position: relative; float: right; }
.pop-inner { width: 450px; height: 350px; position: relative; }
input[name="tabmenu"] { display: none; }
.pcontent { display: none; }
.pcontent img { border-radius: 20px; overflow: hidden; }
.pbtn { position: absolute; right: 20px; top: 15px; }
.pbtn label { background-color: rgb(255, 255, 255); border: 1px solid rgb(204, 204, 204); width: 22px; height: 22px; display: inline-block; border-radius: 50%; cursor: pointer; }
.pbtn button { background-color: rgb(255, 255, 255); border: 1px solid rgb(204, 204, 204); width: 16px; height: 16px; display: inline-block; border-radius: 50%; cursor: pointer; margin: 0px 3px; }
input[id="tab1"]:checked ~ .slide1, input[id="tab2"]:checked ~ .slide2, input[id="tab3"]:checked ~ .slide3, input[id="tab4"]:checked ~ .slide4 { display: block; }
input[id="tab1"]:checked ~ .pbtn label[for="tab1"], input[id="tab2"]:checked ~ .pbtn label[for="tab2"], input[id="tab3"]:checked ~ .pbtn label[for="tab3"], input[id="tab4"]:checked ~ .pbtn label[for="tab4"] { background-color: rgb(0, 116, 229); border: 2px solid rgb(0, 0, 0); }
input[id="tab1"]:checked ~ .pbtn button[id="tab1_pop"], input[id="tab2"]:checked ~ .pbtn button[id="tab2_pop"], input[id="tab3"]:checked ~ .pbtn button[id="tab3_pop"], input[id="tab4"]:checked ~ .pbtn button[id="tab4_pop"] { background-color: rgb(59, 158, 255); border: 1px solid rgb(0, 116, 229); }
.main-fifthcon { display: flex; width: 1400px; margin: 15px auto; }
.onstop-servicearea { width: 100%; position: relative; }
.onestop-list { display: flex; flex-wrap: wrap; }
.onestop-list li { width: 33%; height: 70px; line-height: 70px; padding-left: 20px; margin-right: 5px; box-sizing: border-box; background-color: rgb(235, 245, 255); border: 1px solid rgb(169, 204, 255); box-shadow: rgba(0, 0, 0, 0.07) 2px 3px 2px; border-radius: 15px; margin-bottom: 7px; font-size: 24px; color: rgb(34, 34, 34); font-weight: 600; transition: 0.3s; }
.onestop-list li:hover { background-color: rgb(0, 116, 229); border: 1px solid rgb(0, 116, 229); color: rgb(255, 255, 255); }
.onestop-list a { display: block; }
.onestop-list li:hover a { color: rgb(255, 255, 255); }
.onestop-list li:nth-child(3n) { margin-right: 0px; }
.onestop-list li:nth-child(1) span { background: url("../images/main/onestop-icon1.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
.onestop-list li:nth-child(2) span { background: url("../images/main/onestop-icon2.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
.onestop-list li:nth-child(3) span { background: url("../images/main/onestop-icon3.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
.onestop-list li:nth-child(4) span { background: url("../images/main/onestop-icon4.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
.onestop-list li:nth-child(5) span { background: url("../images/main/onestop-icon5.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
.onestop-list li:nth-child(6) span { background: url("../images/main/onestop-icon6.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
.onestop-list li span { float: right; font-size: 0px; width: 46px; height: 46px; border-radius: 50%; margin: 11px 20px 0px 0px; }
.safenews-area { width: 450px; position: relative; }
.news-titlearea { display: flex; justify-content: space-between; }
.r-btnarea { padding-top: 5px; position: absolute; top: 0px; right: 0px; }
.news-list li { font-size: 18px; color: rgb(34, 34, 34); padding: 15px 0px; border-bottom: 1px dashed rgb(217, 217, 217); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; word-break: break-all; }
.news-list li a { display: contents; }
.news-list li:first-child { padding-top: 0px; }
.news-list li:last-child { border-bottom: 0px; }
@media (max-width: 1386px) {
  .main-firstcon { width: 100%; margin: 0px; padding: 0px 3%; }
  .main-secondcon { width: 100%; margin: 0px; padding: 10px 3% 0px; }
  .calam-guidelist a { display: inline-block; font-size: 16px; color: rgb(34, 34, 34); font-weight: 500; margin: 0px 5px; }
  .main-thirdcon { padding: 0px; width: 100%; margin: 0px; }
  .main-thirdcon .icon-setting a { background: url("../images/main/setting-icon.png") 85% 50% no-repeat rgb(34, 34, 34); padding: 5px 30px 5px 10px; border-radius: 50px; color: rgb(255, 255, 255); float: right; cursor: pointer; position: absolute; top: 10px; right: 1%; }
  .fourth-inner { width: 100%; margin: 0px 0px 60px; display: flex; padding: 60px 3%; }
  .main-fifthcon { display: flex; width: 100%; margin: 0px; padding: 0px 3%; }
  .onestop-list { display: flex; flex-wrap: wrap; }
  .onestop-list li { width: 49.6%; height: 80px; line-height: 80px; padding-left: 20px; margin-right: 5px; box-sizing: border-box; background-color: rgb(235, 245, 255); border: 1px solid rgb(169, 204, 255); box-shadow: rgba(0, 0, 0, 0.07) 2px 3px 2px; border-radius: 20px; margin-bottom: 5px; font-size: 18px; color: rgb(34, 34, 34); font-weight: 600; transition: 0.3s; }
  .onestop-list li:hover { background-color: rgb(0, 116, 229); border: 1px solid rgb(0, 116, 229); color: rgb(255, 255, 255); }
  .onestop-list li:hover a { color: rgb(255, 255, 255); }
  .onestop-list li:nth-child(2n) { margin-right: 0px; }
  .onestop-list li:nth-child(1) span { background: url("../images/main/onestop-icon1.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
  .onestop-list li:nth-child(2) span { background: url("../images/main/onestop-icon2.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
  .onestop-list li:nth-child(3) span { background: url("../images/main/onestop-icon3.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
  .onestop-list li:nth-child(4) span { background: url("../images/main/onestop-icon4.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
  .onestop-list li:nth-child(5) span { background: url("../images/main/onestop-icon5.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
  .onestop-list li:nth-child(6) span { background: url("../images/main/onestop-icon6.png") 50% 50% / 46px auto no-repeat rgb(255, 255, 255); }
  .onestop-list li span { float: right; font-size: 0px; width: 42px; height: 42px; border-radius: 50%; margin: 16px 20px 0px 0px; }
  .quick-list { justify-content: space-around; }
}
@media (max-width: 1280px) {
  .main-content { max-width: 100%; width: 100%; padding: 0px; }
  .main-firstcon { width: 100%; margin: 0px; padding: 0px 2%; }
  .total-searcharea { display: inline-block; padding: 0px; }
  .total-searcharea.mb60 { margin-bottom: 0px; }
  .total-searchform h3 { width: 22%; }
  .total-searchform input { width: 84%; margin: 0px 0px 0px 5%; display: inline-block; }
  .btn-totalsearch { width: 8%; text-align: center; }
  .btn-totalsearch { background: url("../images/main/tatal-search.png") 80% 50% no-repeat; }
